+			RCODE_SET(q->packet, RCODE_REFUSE);
+			/* RFC8914 - Extended DNS Errors
+			 * 4.19. Extended DNS Error Code 18 - Prohibited */
+			q->edns.ede = EDE_PROHIBITED;
+		}
+		break;
+	}
